int Add(int a, int b)
{
    return a + b;
}

string GetPlayerStatus(int health)
{
    if (health > 50)
        return "Healthy";
    else if (health > 0)
        return "Injured";
    else
        return "Defeated";
}

bool IsGameOver(int lives)
{
    return lives <= 0;
}

